+        bold?: boolean;
+        italics?: boolean;
+        underline?: boolean;
+        strike?: boolean;
+        superScript?: boolean;
+        subScript?: boolean;
+      } = {},
+    ) => {
+      if (node.nodeType === Node.TEXT_NODE) {
+        const text = node.textContent ?? "";
+        if (text) runs.push(new TextRun({ text, ...marks }));
+        return;
+      }
+      if (!(node instanceof Element)) return;
+      if (node.tagName === "BR") {
+        runs.push(new TextRun({ break: 1 }));
+        return;
+      }
+      const tag = node.tagName.toLowerCase();
+      const next = {
